1	import XCTest
2	
3	@testable import Workroom
4	
5	/// The Sentry `environment` split (WORKROOM-2B follow-up).
6	///
7	/// The `Nightly` build config is release-type, so it defines no `DEBUG` and nightly events used to
8	/// arrive tagged `production` — a hang from a build that ships nightly from the tip of `master` to a
9	/// handful of people looked exactly like a hang in the released app. `defaultEnvironment` takes its
10	/// inputs as parameters precisely so this can be asserted without faking a build configuration.
11	final class SentryConfigTests: XCTestCase {
12	
13	  func testNightlyReleaseBuildReportsNightly() {
14	    XCTAssertEqual(SentryConfig.defaultEnvironment(nightly: true, debug: false), "nightly")
15	  }
16	
17	  func testShippingReleaseBuildReportsProduction() {
18	    XCTAssertEqual(SentryConfig.defaultEnvironment(nightly: false, debug: false), "production")
19	  }
20	
21	  func testDebugWinsOverEveryOtherIdentity() {
22	    // A local "Workroom Dev" build must never file events as nightly OR production, whatever the
23	    // channel marker says.
24	    XCTAssertEqual(SentryConfig.defaultEnvironment(nightly: true, debug: true), "development")
25	    XCTAssertEqual(SentryConfig.defaultEnvironment(nightly: false, debug: true), "development")
26	  }
27	
28	  func testThisTestHostIsADebugBuild() {
29	    // Sanity check on the defaulted parameter: the test host is built Debug, so the no-argument call
30	    // must agree with the explicit one. Catches the seam being wired to the wrong fact.
31	    XCTAssertTrue(SentryConfig.isDebugBuild)
32	    XCTAssertEqual(SentryConfig.defaultEnvironment(), "development")
33	  }
34	
35	  func testDevBuildNeverStartsSentry() {
36	    XCTAssertFalse(SentryConfig.shouldStart(debug: true))
37	  }
38	
39	  func testReleaseChannelsStartSentry() {
40	    XCTAssertTrue(SentryConfig.shouldStart(debug: false))
41	  }
42	}
